/** Bright, generic paints for the cars of visitors from away (summer's tourists, the fall's leaf-peepers). No makes to name. */
export const VISITOR_PAINT: readonly number[] = [0xe85d75, 0x2fb5c9, 0xf2c230, 0x8bc34a, 0xf4ead8, 0x5c6bc0, 0xff8a3d, 0x9b59b6, 0x1fa38a];

function hash(a: number, b: number, c: number): number {
  let h = Math.imul(a ^ 0x9e3779b9, 0x85ebca6b) ^ Math.imul(b + 0x632be5ab, 0xc2b2ae35) ^ Math.imul(c ^ 0x27d4eb2f, 0x165667b1);
  h ^= h >>> 15; h = Math.imul(h, 0x2c1b3c6d); h ^= h >>> 12; h = Math.imul(h, 0x297a2d39); h ^= h >>> 15;
  return (h >>> 0) / 4294967296;
}

/** Cells of this many metres each hold at most one frost heave. */
const HEAVE_CELL = 60;

/**
 * Mud season's frost heaves: in about three cells in ten, a ridge 1.8 m thick runs across the cell (along x or along z, by a
 * second throw), so a car going the right way down a road there crosses it, and a car on a road the ridge runs along does not.
 * A pure function of the place: the same heave on every screen, nothing stored.
 */
export function heaveAt(x: number, z: number): boolean {
  const i = Math.floor(x / HEAVE_CELL), j = Math.floor(z / HEAVE_CELL);
  if (hash(i, j, 1) >= 0.3) return false;
  const at = 6 + 48 * hash(i, j, 3);
  return hash(i, j, 2) < 0.5 ? Math.abs(x - (i * HEAVE_CELL + at)) < 0.9 : Math.abs(z - (j * HEAVE_CELL + at)) < 0.9;
}
